const CO_TIENG_VIET = /[àáảãạăằắẳẵặâầấẩẫậèéẻẽẹêềếểễệìíỉĩịòóỏõọôồốổỗộơờớởỡợùúủũụưừứửữựỳýỷỹỵđ]/i;
/** Đổi dấu phẩy thập phân sang dấu chấm: "2,1 m" → "2.1 m" (cả dạng LaTeX "2{,}1"). */
export const soAnh = (s) => String(s).replace(/(\d)\{,\}(\d)/g, '$1.$2').replace(/(\d),(\d)/g, '$1.$2');

/** Bản tiếng Anh của một câu, hoặc null nếu chưa dịch. */
export function cauHoiEn(id) { return CAU_HOI_EN[id] ?? null; }

/** Phương án tiếng Anh: bản dịch nếu có; phương án chỉ có số/kí hiệu thì tự đổi dấu thập phân; còn chữ tiếng Việt mà chưa dịch → null. */
export function phuongAnEn(id, key, viText) {
  const d = CAU_HOI_EN[id]?.opts?.[key];
  if (d) return d;
  if (!CAU_HOI_EN[id] || CO_TIENG_VIET.test(String(viText))) return null;
  return soAnh(viText);
}
